    'WITH candidates AS (      SELECT t.__id AS source_id, p.part_idx, f.__id AS foreign_id      FROM %I.%I AS t      CROSS JOIN LATERAL (        SELECT trim(part) AS token, ordinality AS part_idx        FROM unnest(string_to_array(t.%I::text, '','')) WITH ORDINALITY AS parts(part, ordinality)        WHERE trim(part) <> ''''      ) AS p      JOIN %I.%I AS f ON f.%I::text = p.token      WHERE t.%I IS NOT NULL    ), mapped AS (      SELECT source_id, part_idx, foreign_id      FROM candidates    ), picked AS (      SELECT DISTINCT ON (source_id) source_id, foreign_id, part_idx      FROM mapped      ORDER BY source_id, part_idx    )    UPDATE %I.%I AS t    SET %I = p.foreign_id, %I = p.part_idx    FROM picked AS p    WHERE t.__id = p.source_id',
